-- 0014_helpdesk_task.sql — the curated MCP demo task tsk_helpdesk_refunds (U29, ADR-11, plan
-- 20261012-itera-testmyagent-ui-refactor). Bundle: benchmarks/helpdesk-refunds (task.json, seed in
-- mcp/helpdesk/, scorer assertions in tests/hidden/mcp/helpdesk/assert.json, reference calls in
-- solution/mcp-calls.jsonl). It uses the Itera catalog server helpdesk@1 (mcp/catalog/helpdesk).
--
-- task_versions.contract carries what the public task page (U30) reads, per MCP server entry:
--   tools_snapshot (the tools/list the agent sees: the catalog tools.json filtered by allowed_tools),
--   image_digest (ghcr.io/devfellowship/itera-mcp-helpdesk:1, pushed by the CI job mcp-catalog),
--   snapshot_captured_at, seed_digest (sha256 of mcp/helpdesk/seed.json), reviewed_at (null: a
--   catalog server is reviewed in its own PR, not per task).
-- The task_packs row (helpdesk-refunds / 1) is written by the runner at boot (curated-packs.ts):
-- task_packs is owned by postgres with RLS on, so only itera_api_service can write it.
--
-- Same posture as 0000–0013. No table, no function, no trigger. Idempotent. One transaction.

begin;

insert into public.tags (id, name, kind, sort) values ('mcp-helpdesk', 'Help desk (MCP)', 'tool', 9)
on conflict (id) do nothing;

insert into public.tasks (slug, kind, name, description, visibility, status, est_minutes) values
  ('tsk_helpdesk_refunds', 'itera', 'Refund requests in the inbox', 'Refund, deny or escalate each request by the policy, through the helpdesk MCP server.', 'public', 'ready', 4)
on conflict (slug) do nothing;

insert into public.task_versions (task_id, version, source, pack_id, pack_version, hidden_tests_count, runnable, contract, labels)
select t.id, 1, 'curated', 'helpdesk-refunds', '1', 6, true, '{"editable_paths": ["src/**"], "protected_paths": ["tests/**", "package.json", "package-lock.json", "tsconfig.json", "vitest.config.*"], "environment": {"dir": "environment", "allow_internet": false, "cpus": 2, "memory_mb": 2048, "tools": {"builtin": ["read", "write", "edit", "search", "list", "todo"], "mcp": [{"name": "helpdesk", "description": "The shop''s help desk: customers, orders, tickets and refunds (Itera catalog fixture).", "catalog": "helpdesk@1", "transport": "http", "seed": "mcp/helpdesk/seed.json", "allowed_tools": ["search_tickets", "get_customer", "get_order", "issue_refund", "close_ticket", "add_note"], "expose_state_to_scorer": true, "startup_timeout_sec": 30, "tools_snapshot": [{"name": "search_tickets", "description": "List support tickets. Filter by status (open or closed), by customer id, or by a text query on the subject and body. Returns the full ticket: id, customer_id, order_id, subject, body, status, resolution and notes.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"status": {"type": "string", "enum": ["open", "closed"]}, "customer_id": {"type": "string", "maxLength": 20}, "query": {"type": "string", "maxLength": 200}}}}, {"name": "get_customer", "description": "Get one customer by id: name, email and tier.", "inputSchema": {"type": "object", "additionalProperties": false, "required": ["customer_id"], "properties": {"customer_id": {"type": "string", "maxLength": 20}}}}, {"name": "get_order", "description": "Get one order by id: items with unit prices in cents, total_cents, refunded_cents, status and delivered_at.", "inputSchema": {"type": "object", "additionalProperties": false, "required": ["order_id"], "properties": {"order_id": {"type": "string", "maxLength": 20}}}}, {"name": "issue_refund", "description": "Refund an amount in cents on an order, linked to a ticket. The amount must be positive and at most the order total minus what was already refunded. This moves money: it cannot be undone.", "inputSchema": {"type": "object", "additionalProperties": false, "required": ["order_id", "ticket_id", "amount_cents", "reason"], "properties": {"order_id": {"type": "string", "maxLength": 20}, "ticket_id": {"type": "string", "maxLength": 20}, "amount_cents": {"type": "integer", "minimum": 1}, "reason": {"type": "string", "minLength": 1, "maxLength": 500}}}}, {"name": "close_ticket", "description": "Close an open ticket with a resolution: refunded, denied, escalated or answered.", "inputSchema": {"type": "object", "additionalProperties": false, "required": ["ticket_id", "resolution"], "properties": {"ticket_id": {"type": "string", "maxLength": 20}, "resolution": {"type": "string", "enum": ["refunded", "denied", "escalated", "answered"]}}}}, {"name": "add_note", "description": "Add an internal note to a ticket (open or closed).", "inputSchema": {"type": "object", "additionalProperties": false, "required": ["ticket_id", "text"], "properties": {"ticket_id": {"type": "string", "maxLength": 20}, "text": {"type": "string", "minLength": 1, "maxLength": 2000}}}}], "image_digest": "sha256:f107b0e4fdf5c51c7eb542b7eb6b458cce8a911135f8699f9112b8d5e05f9212", "snapshot_captured_at": "2026-10-12T18:00:00Z", "seed_digest": "sha256:67467ec4e9616e854c1af3c218f5c3ecf0ffc5bd70e0ebc4725754ea4168cb38", "reviewed_at": null}]}, "run_egress": ["model-gateway", "mcp"], "secrets": [], "resources": {"cpus": 2, "memory_mb": 2048, "pids": 512}}, "est_minutes": 4, "agent": {"timeout_sec": 300}, "verifier": {"cmd": ["npx", "vitest", "run", "{tests}", "--reporter=json", "--outputFile={report}"], "timeout_sec": 120}, "profile": {"goal": "Work a support inbox through the helpdesk MCP server: refund, deny or escalate each refund request exactly as the refund policy says, and leave the other tickets alone.", "done_when": ["Exactly the refunds that the policy allows are issued, for the correct amounts.", "Each refund ticket is closed as refunded, denied or escalated; the escalation has a note.", "A ticket that is not a refund request stays open and unchanged.", "src/decisions.json records the decision of every closed ticket."], "instruction": "You work the support inbox of an online shop. The help desk is an MCP server named `helpdesk` (tools: search_tickets, get_customer, get_order, issue_refund, close_ticket, add_note). Today is 2026-10-01.\n\nProcess every OPEN ticket that asks for a refund, and follow this refund policy exactly:\n\n1. Refund only an order with status `delivered`, and only within 30 days after its `delivered_at` date.\n2. Refund only the price of the affected items. Example: one broken mug of two = the price of one mug. Use the unit prices in cents from get_order.\n3. Never refund an order that is already fully refunded (`refunded_cents` equals `total_cents`). Deny it.\n4. A refund above 10000 cents (US$100.00) needs a manager. Do NOT issue it. Add a note to the ticket that says why, and close the ticket with the resolution `escalated`.\n5. Close each refund ticket that you decide with the resolution `refunded`, `denied` or `escalated`. Issue at most one refund per ticket.\n6. A ticket that is not a refund request is not yours: do not change it and leave it open.\n\nMoney moves for real in this desk: a refund cannot be undone.\n\nWhen you are done, record your decisions in `src/decisions.json`, one key per ticket that you closed, for example `{\"T-1\": \"refunded\", \"T-2\": \"denied\"}`. Do not edit any file under tests/ -- your work is graded by hidden tests and by the final state of the help desk, and any change under tests/ is out of scope and will be rejected.", "repository": {"repo": "devfellowship/itera-certificacao-onchain", "path": "benchmarks/helpdesk-refunds/environment"}, "public_tests_count": 2, "mcp_scoring": {"scorer": "mcp_state", "weight": 50, "assertions": 14, "reads": "final state of helpdesk (docker exec /itera/export), never a network port"}}}'::jsonb, '{sealed-tests}'::text[]
  from public.tasks t
 where t.slug = 'tsk_helpdesk_refunds'
on conflict (task_id, version) do nothing;

insert into public.task_tags (task_id, tag_id)
select t.id, v.tag_id from (values ('mcp-helpdesk'), ('money-math')) as v(tag_id)
  join public.tasks t on t.slug = 'tsk_helpdesk_refunds'
on conflict do nothing;

commit;
